<?php if ($path==='/blog'): ?>
<section class="page wrap"><div class="eyebrow">MEXA JOURNAL</div><h1>Ideas worth sharing.</h1><p class="lead">Notes and insights from MEXA MOTION.</p><?php $posts=$db->query('SELECT id,title,slug,summary,created_at FROM blog_posts WHERE published=1 ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC); ?><div class="service-grid"><?php if(!$posts): ?><p>No articles published yet.</p><?php endif ?><?php foreach($posts as $post): ?><article class="service-card"><div class="eyebrow"><?=e(substr($post['created_at'],0,10))?></div><h2><?=e($post['title'])?></h2><p><?=e($post['summary'])?></p><p><a href="/article?slug=<?=e(rawurlencode($post['slug']))?>">Read article →</a></p></article><?php endforeach ?></div></section>
<?php elseif ($path==='/article'): ?>
<?php $q=$db->prepare('SELECT * FROM blog_posts WHERE slug=? AND published=1'); $q->execute([(string)($_GET['slug'] ?? '')]); $post=$q->fetch(PDO::FETCH_ASSOC); if (!$post) http_response_code(404); ?><section class="page wrap"><a href="/blog">← Journal</a><?php if (!$post): ?><h1>Article not found.</h1><?php else: ?><div class="eyebrow" style="margin-top:30px"><?=e(substr($post['created_at'],0,10))?></div><h1><?=e($post['title'])?></h1><p class="lead"><?=e($post['summary'])?></p><div class="article-body"><?=nl2br(e($post['body']))?></div><?php endif ?></section>
<?php elseif ($path==='/admin/blog'): ?>
<?php $edit=null; if(isset($_GET['edit'])) { $q=$db->prepare('SELECT * FROM blog_posts WHERE id=?'); $q->execute([(int)$_GET['edit']]); $edit=$q->fetch(PDO::FETCH_ASSOC) ?: null; } $posts=$db->query('SELECT * FROM blog_posts ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC); ?><div class="eyebrow">CONTENT MANAGEMENT</div><h1>Blog</h1><p class="lead">Write and publish articles for the journal.</p><div class="admin-columns"><form class="panel form-grid" method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)($edit['id'] ?? 0)?>"><h2><?=$edit?'Edit post':'New post'?></h2><label>Title<input name="title" maxlength="180" required value="<?=e($edit['title'] ?? '')?>"></label><label>URL slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="180" required value="<?=e($edit['slug'] ?? '')?>"></label><label>Summary<textarea name="summary" maxlength="500"><?=e($edit['summary'] ?? '')?></textarea></label><label>Article (plain text)<textarea name="body" maxlength="50000" required><?=e($edit['body'] ?? '')?></textarea></label><label class="check"><input type="checkbox" name="published" <?=!empty($edit['published'])?'checked':''?>> Published</label><button class="btn">Save post</button></form><div class="panel"><h2>Posts</h2><?php if(!$posts): ?><p>No posts yet.</p><?php endif ?><?php foreach($posts as $p): ?><div class="admin-row"><div><strong><?=e($p['title'])?></strong><small><?=$p['published']?'Published':'Draft'?></small></div><a href="/admin/blog?edit=<?=(int)$p['id']?>">Edit</a></div><?php endforeach ?></div></div>
<?php elseif ($path==='/admin/users'): ?>
<?php $users=$db->query("SELECT id,name,email,role,active,created_at FROM users ORDER BY id DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC); ?><div class="eyebrow">BUSINESS MANAGEMENT</div><h1>Users</h1><p class="lead">Enable or disable customer access. Administrators cannot be changed here.</p><div class="panel"><?php foreach($users as $u): ?><div class="item-row"><div><strong><?=e($u['name'])?></strong><p><?=e($u['email'])?> · <?=e($u['role'])?> · <?=$u['active']?'Active':'Disabled'?></p></div><?php if($u['role']==='user'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input type="hidden" name="active" value="<?=$u['active']?'0':'1'?>"><button class="btn btn-outline btn-small"><?=$u['active']?'Disable':'Enable'?></button></form><?php endif ?></div><?php endforeach ?></div>
<?php endif ?>
